import json


def fingerprint(record):
    """Return the canonical JSON text of the record."""
    return json.dumps(record, sort_keys=True,
                      separators=(",", ":"))

from datetime import datetime

# the four accepted dialects, in try-order
_SHAPES = ("%Y-%m-%d", "%d/%m/%Y", "%Y%m%d", "%Y/%m/%d")


def import_dates(entries):
    """Normalize messy date entries to ISO.

    Returns (accepted ISO strings, rejected originals),
    both in input order.
    """
    accepted, rejected = [], []
    for raw in entries:
        for shape in _SHAPES:
            try:
                parsed = datetime.strptime(raw, shape).date()
            except ValueError:
                continue  # wrong shape OR impossible date
            accepted.append(parsed.isoformat())
            break
        else:
            rejected.append(raw)  # no dialect parsed
    return (accepted, rejected)
